def init_agent():
    return {'known':jnp.full((9,), -1, dtype=jnp.int32), 'positions':jnp.zeros((9,2),jnp.int32), 'evidence':jnp.zeros((1680,),jnp.float32)}


def beliefs(obs, known, evidence):
    ASSIGN = jnp.asarray(ASSIGNMENTS)
    TRIPLES = jnp.asarray(TRIPLE_IDS)
    PAIRS = jnp.asarray(PAIR_IDS)
    ONEHOT = jax.nn.one_hot(ASSIGN, 3)
    SAME = (ASSIGN[:,PAIRS[:,0]] == ASSIGN[:,PAIRS[:,1]]).astype(jnp.float32)
    GROUPS = ((ASSIGN[:,TRIPLES[:,0]] == ASSIGN[:,TRIPLES[:,1]]) & (ASSIGN[:,TRIPLES[:,0]] == ASSIGN[:,TRIPLES[:,2]])).astype(jnp.float32)
    valid = jnp.all((known[None,:] < 0) | (ASSIGN == known[None,:]),axis=1)
    hint_colors = obs.node_features[9:,3:6]
    attached = obs.adjacency_matrix[:9,9:].astype(jnp.float32)
    # Hints are fallible statements by a partner, never private ground truth.
    allowed = jnp.einsum('sc,ic->is', hint_colors.astype(jnp.float32), jnp.eye(3))
    per_card = jnp.einsum('ih,ch->ic', attached, allowed)
    has_hint = jnp.sum(attached,axis=1) > 0
    likes = jnp.where(has_hint[None,:], 0.05+0.95*per_card[jnp.arange(9)[None,:],ASSIGN],1.)
    weights = valid.astype(jnp.float32)*jnp.prod(likes,axis=1)*jnp.exp(evidence-jnp.max(jnp.where(valid,evidence,-1e9)))
    weights = weights/jnp.maximum(jnp.sum(weights),1e-20)
    probs = jnp.einsum('s,sic->ic',weights,ONEHOT)
    return weights,probs,weights@SAME,weights@GROUPS


def geometry(positions):
    TRIPLES = jnp.asarray(TRIPLE_IDS)
    d = jnp.sum(jnp.abs(positions[..., :, None, :] - positions[..., None, :, :]),axis=-1)
    adj = d == 1
    td = jnp.stack([d[...,TRIPLES[:,0],TRIPLES[:,1]],d[...,TRIPLES[:,0],TRIPLES[:,2]],d[...,TRIPLES[:,1],TRIPLES[:,2]]],axis=-1)
    connected = jnp.sum(td==1,axis=-1)>=2
    return d,adj,td,connected


def agent_act(obs, reset, memory, rng):
    PAIRS = jnp.asarray(PAIR_IDS)
    GROUP_IDS = jnp.asarray(ASSIGNMENT_GROUPS)
    CELLS = jnp.stack([jnp.arange(81)//9,jnp.arange(81)%9],axis=-1)
    MOVE_CARD = jnp.arange(729)//81
    MOVE_CELL = jnp.arange(729)%81
    memory = jax.tree.map(lambda initial,old:jnp.where(reset,initial,old),init_agent(),memory)
    seen = jnp.sum(obs.node_features[:9,:3],axis=1)>0
    known = jnp.where(seen,jnp.argmax(obs.node_features[:9,:3],axis=1),memory["known"])
    old_d,old_adj,old_td,old_connected = geometry(memory['positions'])
    now_d,now_adj,now_td,now_connected = geometry(obs.positions)
    partner_seen = obs.node_features[:9,9].astype(jnp.float32)
    pair_seen = partner_seen[PAIRS[:,0]]*partner_seen[PAIRS[:,1]]
    change = now_adj[PAIRS[:,0],PAIRS[:,1]].astype(jnp.float32)-old_adj[PAIRS[:,0],PAIRS[:,1]].astype(jnp.float32)
    assignment = jnp.asarray(ASSIGNMENTS)
    same = (assignment[:,PAIRS[:,0]]==assignment[:,PAIRS[:,1]]).astype(jnp.float32)
    delta = same@(pair_seen*change)
    partner_moved = (obs.node_features[0,10]==0)&(obs.node_features[0,11]==3)&jnp.any(obs.positions!=memory['positions'])&~reset
    evidence = memory['evidence']+jnp.where(partner_moved,2.5*jnp.clip(delta,-2.,2.),0.)
    evidence = evidence-jnp.max(evidence)
    weights,probs,pairprob,tripleprob = beliefs(obs,known,evidence)
    d,adj,td,connected = geometry(obs.positions)
    success = jnp.sum(weights*jnp.all(connected[GROUP_IDS],axis=1))
    # Evaluate every native move against the current posterior.
    moved = jnp.broadcast_to(obs.positions,(729,9,2))
    moved = moved.at[jnp.arange(729),MOVE_CARD].set(CELLS[MOVE_CELL])
    md,ma,mt,mc = geometry(moved)
    edges = ma[:,PAIRS[:,0],PAIRS[:,1]].astype(jnp.float32)@pairprob
    groups = mc.astype(jnp.float32)@tripleprob
    distance = (jnp.sum(mt,axis=-1)-jnp.max(mt,axis=-1)).astype(jnp.float32)@tripleprob
    score = edges + .7*groups - .06*distance
    # Preserve greater public legibility when values are tied.
    score += .001*(known[MOVE_CARD]>=0)
    move_action = 10+jnp.argmax(jnp.where(obs.legal_actions[10:739],score,-1e9))
    # Connectivity and occupancy rules also allow inspection decisions to
    # anticipate the next move before its native action mask is available.
    reachable = jnp.broadcast_to(jnp.arange(9)==0,(729,9))
    reachable = jax.lax.fori_loop(0,8,lambda _,reach:jnp.any(ma & reach[:,:,None],axis=1)|reach,reachable)
    unoccupied = ~jnp.any(jnp.all(CELLS[MOVE_CELL,None,:]==obs.positions[None,:,:],axis=-1),axis=1)
    unlocked = obs.node_features[MOVE_CARD,8]==0
    possible = jnp.all(reachable,axis=1)&unoccupied&unlocked
    assignment = jnp.asarray(ASSIGNMENTS)
    triples = jnp.asarray(TRIPLE_IDS)
    same = (assignment[:,PAIRS[:,0]]==assignment[:,PAIRS[:,1]]).astype(jnp.float32)
    triples_same = ((assignment[:,triples[:,0]]==assignment[:,triples[:,1]]) & (assignment[:,triples[:,0]]==assignment[:,triples[:,2]])).astype(jnp.float32)
    joint = (jax.nn.one_hot(assignment,3)*weights[:,None,None]).reshape((1680,27)).T
    conditional_pair = joint@same
    conditional_triple = joint@triples_same
    edge_geometry = ma[:,PAIRS[:,0],PAIRS[:,1]].astype(jnp.float32)
    group_geometry = .7*mc.astype(jnp.float32)-.06*(jnp.sum(mt,axis=-1)-jnp.max(mt,axis=-1))
    conditional_values = edge_geometry@conditional_pair.T+group_geometry@conditional_triple.T
    best_conditional = jnp.max(jnp.where(possible[:,None],conditional_values,-1e9),axis=0).reshape((9,3))
    entropy = 1-jnp.sum(probs**2,axis=1)
    observe_score = jnp.sum(best_conditional,axis=1)+.08*entropy
    observe_action = 1+jnp.argmax(jnp.where(obs.legal_actions[1:10],observe_score,-1e9))
    hint_colors = obs.node_features[9:,3:6].astype(jnp.float32)
    hint_ok = hint_colors@probs.T
    incident = adj.astype(jnp.float32)*jnp.einsum('ic,jc->ij',probs,probs)
    stable = jnp.sum(incident,axis=1)
    card_hint_value = 4*hint_ok + .4*stable[None,:] + .1*(known>=0)[None,:]
    at_cell = jnp.all(CELLS[:,None,:]==obs.positions[None,:,:],axis=-1)
    placement_value = card_hint_value@at_cell.T.astype(jnp.float32)
    hint_scores = jnp.concatenate([jnp.full((4,),10.),placement_value.reshape(-1)])
    hint_action = 739+jnp.argmax(jnp.where(obs.legal_actions[739:1067],hint_scores,-1e9))
    placed = jnp.sum(obs.node_features[9:,8])
    stop = success >= jnp.where(placed>=3,.35,.90)
    substep = obs.node_features[0,11]
    action = jnp.where(substep<2,observe_action,jnp.where(substep==2,move_action,hint_action))
    action = jnp.where(obs.legal_actions[1067]&stop,1067,action)
    action = jnp.where(obs.node_features[0,10]>0,action,0).astype(jnp.int32)
    return action,{'known':known.astype(jnp.int32),'positions':obs.positions,'evidence':evidence},{'success_probability':success,'known':known,'color_probabilities':probs,'legality_errors':jnp.where((substep==2)&(obs.node_features[0,10]>0),jnp.sum(possible!=obs.legal_actions[10:739]),0),'observation_value':observe_score,'move_value':jnp.max(jnp.where(obs.legal_actions[10:739],score,-1e9))}
